\begin{definition}
\label{def:6-44-extra-2}




Let $N$, $M$, and $S$ be smooth manifolds. A family of maps $\{F_s:N\to M\}_{s\in S}$ is smooth if the associated map
\[
F:N\times S\to M,
\qquad F(x,s)=F_s(x),
\]
is smooth.
\end{definition}
